 */
public record ReceiptRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String receiptKey,
        @NotBlank @Size(max = 64) String reservationId,
        @NotNull Long occurredAt
) {
}

